    RETURN avg(size(collect(DISTINCT p))) AS avg_goal_scoring_players, size(matches) AS total_matches
}
RETURN t.name AS tournament_name, avg_goal_scoring_players, total_matches;

MATCH (m:Manufacturer)-[r:REGISTERED]->(c:Case)
