ORDER BY Manufacturer, ReporterOccupation;

MATCH (c:Case)-[r:RESULTED_IN]->(o:Outcome {outcome: 'Death'})
RETURN c.gender AS gender, AVG(c.age) AS average_age, COUNT(c.primaryid) AS total_cases
GROUP BY c.gender;

MATCH (t:Tournament)-[p:PARTICIPATED_IN]->(m:Match)
WITH t, m, size((m)-[:PLAYED_IN]->()) AS player_count
CALL {
    WITH m, player_count
    MATCH (s:Squad)-[n:NAMED]->(t)
    RETURN s.id AS squad_id, player_count / size(collect(DISTINCT m)) AS avg_players_per_squad
}
RETURN t.name AS tournament_name, avg_players_per_squad
ORDER BY tournament_name;

